create function public.review_pa28_batch2_graph() returns integer
language plpgsql security definer set search_path=pg_catalog,public as $$
declare item jsonb; reference jsonb; v uuid; source_id uuid; model_id uuid; ref_id uuid; model_name text; count_rows integer:=0;
begin
 perform pg_advisory_xact_lock(hashtextextended('review-pa28-batch2',0));
 for item in select value from jsonb_array_elements('[{"type":"AD","number":"2024-10-04","hash":"db153059646d6ceeb8b85a66be8d9609cf47d6c2c4ef5ed87572dc312e8205d4","models":["PA-28-181"],"page":4,"published_url":"https://www.govinfo.gov/content/pkg/FR-2024-05-22/pdf/2024-11143.pdf","excerpt":"Paragraph (c) includes PA-28-181 airplanes, certificated in any category, with serial numbers identified in Piper Service Bulletin No. 1413, dated April 9, 2024.","conditions":{"serial_scope":"The serial list is incorporated by reference from Piper SB 1413. That bulletin has not been retrieved; the profile cannot determine serial applicability.","effective_date":"2024-06-06","compliance":"Required actions, exceptions, prior work and reporting must be evaluated from the complete AD. Compliance is not recorded.","publication":"Final published rule, 89 FR 44914-44917, FR document 2024-11143; physical PDF page 4 is printed page 44917."},"references":[{"authority":"PIPER","key":"SB:1413:2024-04-09","label":"Piper SB 1413 - April 9, 2024","page":4,"section":"(k)(2)(i)","excerpt":"Paragraph (k)(2)(i) incorporates Piper Service Bulletin No. 1413, dated April 9, 2024.","conditions":{"source_text":"The AD reference is verified. The bulletin text and its serial list have not been retrieved."}}]},{"type":"STC","number":"SA09252AC-D","hash":"22c9c66fedeed94d1b9d7ae92c1bb380b923b8941676858dcae25a5781a74bdd","models":["PA-28-181"],"page":1,"excerpt":"The certificate lists PA-28-181 under type certificate 2A13 for installation of S-TEC System 30 ALT Altitude Hold System, Model ST-704, with a 14-volt system.","conditions":{"installation":"Not confirmed on an individual aircraft. The installer must determine compatibility with previously approved modifications (page 2, condition 5).","required_data":"Bulletin No. 804 and Master Drawing List No. 921010, both June 25, 1997, or later FAA-approved revisions; 14-volt system.","flight_manual":"For PA-28-181, approved POH/AFM supplement P/N 891444, June 30, 1997, or later FAA-approved revision, is required (page 2, condition 2).","other_models":"The SA2969SW engine-conversion condition concerns PA-28-151; it is not asserted as a PA-28-181 dependency."},"references":[{"authority":"STEC","key":"AFMS:891444:1997-06-30","label":"S-TEC AFM supplement 891444 - June 30, 1997","page":2,"section":"Condition 2","excerpt":"Condition 2 requires approved POH/AFM supplement P/N 891444, dated June 30, 1997, for PA-28-181, or later FAA-approved revisions.","conditions":{"source_text":"The reference is verified in the certificate. The supplement text has not been retrieved."}},{"authority":"STEC","key":"BULLETIN:804:1997-06-25","label":"S-TEC Bulletin 804 - June 25, 1997","page":1,"excerpt":"Installation is according to Bulletin No. 804, dated June 25, 1997, or later FAA-approved revision.","conditions":{"source_text":"The referenced design-data document has not been retrieved."}},{"authority":"STEC","key":"MDL:921010:1997-06-25","label":"S-TEC drawing list 921010 - June 25, 1997","page":1,"excerpt":"Installation is according to Master Drawing List No. 921010, dated June 25, 1997, or later FAA-approved revision.","conditions":{"source_text":"The referenced design-data document has not been retrieved."}}]},{"type":"STC","number":"SA09257AC-D","hash":"9d3fe37e2a6e667fe482ebebc29415605fec920c08ea14e6014085389a556849","models":["PA-28-140"],"page":1,"excerpt":"The certificate lists PA-28-140 under type certificate 2A13 for installation of S-TEC System 30 ALT Altitude Hold System, Model ST-712, with a 14-volt system.","conditions":{"installation":"Not confirmed on an individual aircraft. The installer must determine compatibility with previously approved modifications (page 2, condition 6).","required_data":"Bulletin No. 812 and Master Drawing List No. 921012, both July 8, 1997, or later FAA-approved revisions; 14-volt system.","flight_manual":"For PA-28-140, approved POH/AFM supplement P/N 891454, July 11, 1997, or later FAA-approved revision, is required (page 2, condition 3).","other_models":"Serial limitations and the SA2143WE Robertson STOL condition concern PA-28-235, not PA-28-140."},"references":[{"authority":"STEC","key":"AFMS:891454:1997-07-11","label":"S-TEC AFM supplement 891454 - July 11, 1997","page":2,"section":"Condition 3","excerpt":"Condition 3 requires approved POH/AFM supplement P/N 891454, dated July 11, 1997, for PA-28-140, or later FAA-approved revisions.","conditions":{"source_text":"The reference is verified in the certificate. The supplement text has not been retrieved."}},{"authority":"STEC","key":"BULLETIN:812:1997-07-08","label":"S-TEC Bulletin 812 - July 8, 1997","page":1,"excerpt":"Installation is according to Bulletin No. 812, dated July 8, 1997, or later FAA-approved revision.","conditions":{"source_text":"The referenced design-data document has not been retrieved."}},{"authority":"STEC","key":"MDL:921012:1997-07-08","label":"S-TEC drawing list 921012 - July 8, 1997","page":1,"excerpt":"Installation is according to Master Drawing List No. 921012, dated July 8, 1997, or later FAA-approved revision.","conditions":{"source_text":"The referenced design-data document has not been retrieved."}}]},{"type":"STC","number":"SA4930SW","hash":"7b34636f3f05ca717f324f604774141db72b69ccf0ffa93736aef0fd892227bc","models":["PA-28-140","PA-28-181"],"page":1,"series_scope":true,"excerpt":"The certificate identifies PA-28 Series under type certificate 2A13 for installation of the Safe Flight SC-150 Angle of Attack System.","conditions":{"scope_basis":"The original states PA-28 Series, rather than enumerating variants. The selected models are independently reviewed members of type certificate 2A13; only these two supported models are mapped.","installation":"Not confirmed on an individual aircraft. The installer must determine compatibility with previously approved modifications.","required_data":"Installation Manual Supplement dated June 1982, or later FAA-approved revision, and FAA-approved Airplane Flight Manual Supplement dated February 15, 1983."},"references":[{"authority":"STC-SA4930SW","key":"AFMS:1983-02-15","label":"SC-150 AFM supplement - February 15, 1983","page":1,"excerpt":"An FAA-approved Airplane Flight Manual Supplement dated February 15, 1983, is required.","conditions":{"source_text":"The reference is verified in the certificate. The supplement text has not been retrieved; identity is scoped to STC SA4930SW."}},{"authority":"STC-SA4930SW","key":"INSTALLATION-SUPPLEMENT:1982-06","label":"SC-150 installation supplement - June 1982","page":1,"excerpt":"Installation is in accordance with the Installation Manual Supplement dated June 1982, or later FAA-approved revision.","conditions":{"source_text":"The reference is verified in the certificate. The manual text has not been retrieved; identity is scoped to STC SA4930SW."}}]}]'::jsonb) loop
  select dv.id into v from public.document_versions dv join public.documents d on d.id=dv.document_id
   where d.authority='FAA' and d.document_type=item->>'type' and d.document_number=item->>'number' and dv.content_sha256=item->>'hash'
    and dv.status='current' and dv.is_published and d.is_published
    and (not (item ? 'published_url') or (dv.metadata->>'original_source_url'=item->>'published_url' and dv.metadata->>'original_source_kind'='final_federal_register'))
    and exists(select 1 from public.related_document_matches match where match.version_id=dv.id and match.is_active) limit 1;
  if v is null then raise exception 'Verified current original or publication provenance missing'; end if;
  insert into public.catalog_entities(authority,entity_type,natural_key,label,is_published) values('FAA','certificate',(item->>'type')||':'||(item->>'number'),(item->>'type')||' '||(item->>'number'),true)
   on conflict(authority,entity_type,natural_key) do update set is_published=true returning id into source_id;
  for model_name in select jsonb_array_elements_text(item->'models') loop
   select id into model_id from public.catalog_entities where authority='FAA' and entity_type='aircraft_model' and natural_key=model_name;
   if model_id is null or not exists(select 1 from public.related_document_matches where version_id=v and model=model_name and is_active) then raise exception 'Current model index missing'; end if;
   if coalesce((item->>'series_scope')::boolean,false) and not exists(select 1 from public.model_graph where model=model_name and relationship_type='covered_by' and source_document_type='TCDS' and basis_key='TCDS:2A13') then raise exception 'Reviewed series membership missing'; end if;
   insert into public.relationships(source_entity_id,target_entity_id,relationship_type,evidence_version_id,evidence_page,evidence_excerpt,applicability_conditions,review_status,is_published)
    select source_id,model_id,case item->>'type' when 'AD' then 'applies_to' else 'approved_for' end,v,(item->>'page')::integer,item->>'excerpt',item->'conditions','reviewed',true
    where not exists(select 1 from public.relationships where source_entity_id=source_id and target_entity_id=model_id and evidence_version_id=v);
   count_rows:=count_rows+1;
  end loop;
  for reference in select value from jsonb_array_elements(item->'references') loop
   insert into public.catalog_entities(authority,entity_type,natural_key,label,is_published)
    values(reference->>'authority','service_document',reference->>'key',reference->>'label',true)
    on conflict(authority,entity_type,natural_key) do update set is_published=true returning id into ref_id;
   insert into public.relationships(source_entity_id,target_entity_id,relationship_type,evidence_version_id,evidence_page,evidence_section,evidence_excerpt,applicability_conditions,review_status,is_published)
    select source_id,ref_id,'references',v,(reference->>'page')::integer,reference->>'section',reference->>'excerpt',reference->'conditions','reviewed',true
    where not exists(select 1 from public.relationships where source_entity_id=source_id and target_entity_id=ref_id and evidence_version_id=v and relationship_type='references');
   count_rows:=count_rows+1;
  end loop;
 end loop;
 return count_rows;
end $$;
revoke all on function public.review_pa28_batch2_graph() from public,anon,authenticated;
grant execute on function public.review_pa28_batch2_graph() to service_role;

create or replace view public.model_graph with(security_invoker=true) as
select r.id,d.document_number as tcds_number,s.label as model,t.label as target,t.entity_type as target_type,
  r.relationship_type,r.evidence_page,r.evidence_excerpt,r.applicability_conditions,v.revision_label as evidence_revision,v.source_url,
  d.document_number as source_document_number,d.document_type as source_document_type,t.natural_key as basis_key,
  null::text as path_via,'outgoing'::text as direction,v.id as evidence_version_id,
  s.id as source_entity_id,t.id as target_entity_id,s.id as model_entity_id,null::uuid as via_entity_id,r.evidence_attachment_id,a.file_name as evidence_file_name,v.metadata->>'original_source_url' as original_source_url
from public.relationships r join public.catalog_entities s on s.id=r.source_entity_id join public.catalog_entities t on t.id=r.target_entity_id
join public.document_versions v on v.id=r.evidence_version_id join public.documents d on d.id=v.document_id left join public.source_attachments a on a.id=r.evidence_attachment_id
where r.review_status='reviewed' and r.is_published and v.is_published and d.is_published and s.is_published and t.is_published and s.entity_type='aircraft_model' and d.authority='FAA' and d.document_type='TCDS' and v.id=d.current_version_id and (r.evidence_attachment_id is null or a.is_active)
union all
select r.id,'2A13',t.label,s.label,s.entity_type,r.relationship_type,r.evidence_page,r.evidence_excerpt,r.applicability_conditions,v.revision_label,v.source_url,
  d.document_number,d.document_type,s.natural_key,null::text,'incoming'::text,v.id,s.id,t.id,t.id,null::uuid,r.evidence_attachment_id,a.file_name,v.metadata->>'original_source_url'
from public.relationships r join public.catalog_entities s on s.id=r.source_entity_id join public.catalog_entities t on t.id=r.target_entity_id
join public.document_versions v on v.id=r.evidence_version_id join public.documents d on d.id=v.document_id left join public.source_attachments a on a.id=r.evidence_attachment_id
where r.review_status='reviewed' and r.is_published and v.is_published and d.is_published and s.is_published and t.is_published and t.entity_type='aircraft_model' and d.authority='FAA' and d.document_type in('AD','STC') and v.status='current' and (r.evidence_attachment_id is null or a.is_active)
  and exists(select 1 from public.related_document_matches m where m.version_id=v.id and m.model=t.label and m.is_active)
union all
select r.id,'2A13',m.label,t.label,t.entity_type,r.relationship_type,r.evidence_page,r.evidence_excerpt,r.applicability_conditions,v.revision_label,v.source_url,
  d.document_number,d.document_type,t.natural_key,s.label,'outgoing'::text,v.id,s.id,t.id,m.id,s.id,r.evidence_attachment_id,a.file_name,v.metadata->>'original_source_url'
from public.relationships r join public.catalog_entities s on s.id=r.source_entity_id join public.catalog_entities t on t.id=r.target_entity_id
join public.document_versions v on v.id=r.evidence_version_id join public.documents d on d.id=v.document_id left join public.source_attachments a on a.id=r.evidence_attachment_id
join public.relationships scope on scope.source_entity_id=s.id and scope.evidence_version_id=v.id and scope.relationship_type in('applies_to','approved_for')
join public.catalog_entities m on m.id=scope.target_entity_id and m.entity_type='aircraft_model'
where r.review_status='reviewed' and r.is_published and v.is_published and d.is_published and s.is_published and t.is_published and scope.review_status='reviewed' and scope.is_published and m.is_published and r.relationship_type='references' and d.authority='FAA' and d.document_type in('AD','STC') and v.status='current' and (r.evidence_attachment_id is null or a.is_active)
  and (scope.evidence_attachment_id is null or exists(select 1 from public.source_attachments sa where sa.id=scope.evidence_attachment_id and sa.is_active))
  and exists(select 1 from public.related_document_matches active where active.version_id=v.id and active.model=m.label and active.is_active);
